setup.script:
#!/bin/sh
# the other computer: it answers `kith remote _run` with one result and nothing else; down: ssh itself fails
case "$*" in
  *"remote _run"*) [ -n "${ASK_SSH_DOWN:-}" ] && { echo "ssh: connect to host mini port 22: No route to host" >&2; exit 255; }
                   printf '{"answer":"hi from mini","session_id":"r1","cost_usd":0.02}\n' ;;
  *) exit 255 ;;
esac

